const pagos = $input.all().json;
if (!pagos || pagos.length === 0) {
  return [{ json: { skip: true, reason: 'No hay pagos por vencer' } }];
}

const resultados = pagos.map(p => {
  const nombre = `${p.nombres || ''} ${p.apellidos || ''}`.trim();
  const valor = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP' }).format(p.valor_pagado);
  const dias = p.dias_restantes;

  let urgencia = '';
  if (dias <= 0) urgencia = '⚠️ *VENCE HOY*';
  else if (dias === 1) urgencia = '⚠️ *VENCE MAÑANA*';
  else urgencia = `📅 Vence en *${dias} días*`;

  const mensaje = `🏋️ *MetaFit — Recordatorio de Pembresía*\n\nHola ${nombre},\n\nTu membresía está por vencer:\n\n${urgencia}\n💰 Valor: *${valor}*\n📆 Vence: ${p.fecha_vencimiento}\n\nAcércate a la sede para renovar. ¡Te esperamos! 💪\n_ Sport Gym Sede 80_`;

  return {
    json: {
      nombre,
      correo: p.correo,
      telefono: p.telefono,
      id_afiliado: p.id_afiliado,
      valor,
      dias,
      fecha_vencimiento: p.fecha_vencimiento,
      mensaje,
      skip: false
    }
  };
});

return resultados;

